Here's a robust Python implementation for the Snowflake SQL API v2 that covers async execution, polling, timeout handling, and idempotent retries:

```python
import http.client
import json
import time
import uuid
from typing import Optional, Dict, Any, List

class SnowflakeSQLClient:
    def __init__(self, account: str, token: str, warehouse: str, database: str, schema: str):
        self.host = f"{account}.snowflakecomputing.com"
        self.token = token
        self.warehouse = warehouse
        self.database = database
        self.schema = schema
        self.session = http.client.HTTPSConnection(self.host)

    def _get_headers(self) -> Dict[str, str]:
        return {
            "Authorization": f"Bearer {self.token}",
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "MyApp/1.0",
            "X-Snowflake-Authorization-Token-Type": "KEYPAIR_JWT"
        }

    def submit_statement(self, sql: str, bindings: Optional[Dict] = None, 
                        async_mode: bool = True, request_id: Optional[str] = None) -> Dict[str, Any]:
        """Submit a SQL statement with optional bindings and async execution."""
        if request_id is None:
            request_id = str(uuid.uuid4())

        payload = {
            "statement": sql,
            "database": self.database,
            "schema": self.schema,
            "warehouse": self.warehouse,
            "bindings": bindings or {}
        }

        url = f"/api/v2/statements?requestId={request_id}&async={str(async_mode).lower()}"

        try:
            self.session.request("POST", url, body=json.dumps(payload), headers=self._get_headers())
            response = self.session.getresponse()
            status = response.status
            body = json.loads(response.read().decode())

            if status == 200:
                return {"status": "complete", "data": body}
            elif status == 202:
                return {"status": "running", "handle": body.get("statementHandle"), 
                        "status_url": body.get("statementStatusUrl")}
            elif status == 408:
                # Timeout but we still have the handle to poll
                return {"status": "timeout", "handle": body.get("statementHandle"),
                        "message": "Query timed out but may still be running"}
            else:
                return {"status": "error", "code": status, "details": body}

        except Exception as e:
            # Idempotent retry logic - same request_id prevents duplicate execution
            raise Exception(f"Submission failed: {str(e)}. Retry with same request_id for idempotency.")

    def poll_status(self, statement_handle: str, max_polls: int = 60, poll_interval: int = 1) -> Dict[str, Any]:
        """Poll the status URL until completion or failure."""
        url = f"/api/v2/statements/{statement_handle}"

        for i in range(max_polls):
            try:
                self.session.request("GET", url, headers=self._get_headers())
                response = self.session.getresponse()
                status = response.status
                body = json.loads(response.read().decode())

                if status == 200:
                    return {"status": "complete", "data": body}
                elif status == 202:
                    time.sleep(poll_interval)
                    continue
                elif status == 408:
                    # Still running, preserve handle and continue polling
                    time.sleep(poll_interval)
                    continue
                else:
                    return {"status": "error", "code": status, "details": body}

            except Exception as e:
                if i == max_polls - 1:
                    raise Exception(f"Polling failed after {max_polls} attempts: {str(e)}")
                time.sleep(poll_interval * 2)  # Exponential backoff

        return {"status": "timeout", "message": "Max polling attempts reached"}

    def execute_with_retry(self, sql: str, bindings: Optional[Dict] = None, 
                          max_retries: int = 3) -> Dict[str, Any]:
        """Execute with automatic retry on connection drops using idempotent request_id."""
        request_id = str(uuid.uuid4())

        for attempt in range(max_retries):
            try:
                result = self.submit_statement(sql, bindings, async_mode=True, request_id=request_id)

                if result["status"] == "running" or result["status"] == "timeout":
                    return self.poll_status(result["handle"])
                elif result["status"] == "complete":
                    return result
                elif result["status"] == "error":
                    # Don't retry on logical errors (400, 422)
                    if result["code"] in [400, 422]:
                        return result
                    # Retry on transient errors
                    if attempt == max_retries - 1:
                        return result
                    time.sleep(2 ** attempt)  # Exponential backoff

            except Exception as e:
                if attempt == max_retries - 1:
                    raise
                time.sleep(2 ** attempt)

        return {"status": "error", "message": "Max retries exceeded"}

# Usage example:
# client = SnowflakeSQLClient("myaccount", "mytoken", "MY_WH", "MY_DB", "MY_SCHEMA")
# result = client.execute_with_retry(
#     "SELECT * FROM users WHERE id = ?", 
#     bindings={"1": {"type": "FIXED", "value": "123"}}
# )
```

Key features:
1. **Idempotent retries**: Uses `requestId` parameter so network failures can be retried safely
2. **Async handling**: Properly processes 202 responses and polls the `statementStatusUrl`
3. **408 timeout resilience**: Preserves the statement handle even on timeout to continue polling
4. **Correct headers**: Includes all required auth and content headers
5. **Bound parameters**: Supports Snowflake's binding syntax with type information
6. **Error handling**: Distinguishes between retryable (network) and non-retryable (SQL error) failures

Make sure to replace the account, token, and database identifiers with your actual Snowflake credentials.

Here is a robust Python client structure for syncing ServiceNow incidents using the Table API. It handles `sysparm_query` encoding, offset pagination, idempotent upserts, and exponential backoff for rate limits.

```python
import requests
import time
from typing import List, Dict, Optional

class ServiceNowClient:
    def __init__(self, instance: str, username: str, password: str):
        self.base_url = f"https://{instance}.service-now.com/api/now/table"
        self.session = requests.Session()
        self.session.auth = (username, password)
        self.session.headers.update({"Accept": "application/json"})

    def _request(self, method: str, endpoint: str, params: Optional[Dict] = None, data: Optional[Dict] = None) -> Dict:
        """Handles request with retry logic for 429 Rate Limiting."""
        url = f"{self.base_url}/{endpoint}"
        max_retries = 3

        for attempt in range(max_retries):
            try:
                resp = self.session.request(method, url, params=params, json=data)

                if resp.status_code == 429:
                    retry_after = int(resp.headers.get('Retry-After', 60))
                    print(f"Rate limited. Waiting {retry_after}s...")
                    time.sleep(retry_after)
                    continue

                resp.raise_for_status()
                return resp.json().get('result', {})

            except requests.exceptions.RequestException as e:
                if attempt == max_retries - 1:
                    raise
                time.sleep(2 ** attempt)

    def get_incidents(self, query: str, limit: int = 100) -> List[Dict]:
        """Fetches incidents with offset pagination."""
        all_records = []
        offset = 0

        while True:
            params = {
                "sysparm_query": query,
                "sysparm_limit": limit,
                "sysparm_offset": offset,
                "sysparm_fields": "sys_id,number,short_description,state,assigned_to"
            }

            batch = self._request("GET", "incident", params=params)
            if not batch:
                break

            all_records.extend(batch)
            if len(batch) < limit:
                break
            offset += limit

        return all_records

    def upsert_incident(self, sys_id: Optional[str], data: Dict) -> Dict:
        """Idempotent upsert: PATCH if exists, POST if new."""
        if sys_id:
            # Verify existence first to ensure idempotency if needed, 
            # or just attempt PATCH and fallback to POST on 404
            return self._request("PATCH", f"incident/{sys_id}", data=data)
        else:
            return self._request("POST", "incident", data=data)

# Usage Example
if __name__ == "__main__":
    client = ServiceNowClient("dev12345", "admin", "password")

    # Encode query: active=true^priority=1
    incidents = client.get_incidents("active=true^priority=1")

    for inc in incidents:
        # Perform local logic, then upsert
        update_data = {"state": "in_progress"}
        result = client.upsert_incident(inc.get('sys_id'), update_data)
        print(f"Updated {result.get('number')}")
```

### Key Implementation Details:
1.  **Query Encoding**: ServiceNow uses caret (`^`) for AND and `OR` for disjunctions. The `sysparm_query` parameter accepts this encoded string directly.
2.  **Pagination**: The loop increments `sysparm_offset` by `sysparm_limit` until the returned batch is smaller than the limit.
3.  **Rate Limiting**: The `_request` method catches HTTP 429, reads the `Retry-After` header, and sleeps before retrying.
4.  **Error Handling**: Structured errors from ServiceNow usually come in the `error` key of the response if not 2xx; this script relies on `raise_for_status()` but can be extended to parse `resp.json().get('error')` for detailed messaging.
